<?php
namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class UpdateProductVariantRequest extends FormRequest { public function authorize():bool{return $this->user()->can('product-variants.edit');} public function rules():array{$v=$this->route('product_variant');return ['product_id'=>['required','exists:products,id'],'unit_id'=>['nullable','exists:units,id'],'name'=>['required','string','max:150'],'sku'=>['required','string','max:100',Rule::unique('product_variants','sku')->ignore($v)],'barcode'=>['nullable','string','max:100',Rule::unique('product_variants','barcode')->ignore($v)],'attributes'=>['nullable','array'],'attributes.*'=>['nullable','string','max:100'],'cost_price'=>['required','numeric','min:0'],'selling_price'=>['required','numeric','min:0'],'conversion_factor'=>['required','numeric','gt:0'],'stock_quantity'=>['nullable','numeric','min:0'],'status'=>['boolean']];}}
